from fastmcp import FastMCP
import sys

server = FastMCP("message-templates")

@server.resource("message://summarize/{text}")
def get_summarize_message(text: str):
    """Get a message template asking to summarize the given text"""
    return {
        "type": "text",
        "text": f"Please summarize the following text:\n\n{text}"
    }

if __name__ == "__main__":
